package com.library.lms.dto.response;

import com.library.lms.entity.FinePayment;
import lombok.Getter;

import java.math.BigDecimal;

/**
 * Payment receipt view. payment_date is generated by the database and is not exposed
 * here, so responses stay deterministic and do not depend on a refresh.
 */
@Getter
public class FinePaymentResponse {

    private final Long paymentId;
    private final Long fineId;
    private final BigDecimal amount;
    private final FinePayment.Method paymentMethod;
    private final String referenceNumber;
    private final Long receivedBy;

    public FinePaymentResponse(FinePayment payment) {
        this.paymentId = payment.getPaymentId();
        this.fineId = payment.getFine().getFineId();
        this.amount = payment.getAmount();
        this.paymentMethod = payment.getPaymentMethod();
        this.referenceNumber = payment.getReferenceNumber();
        this.receivedBy = payment.getReceivedBy().getUserId();
    }
}
